// dist/web/bindings/js/web/worker-spec.js
function workerSpec(wasm2) {
  let bool = {
    // We avoid returning zero for false to ensure that the
    // wait_until_non_zero call below terminates.
    there: (bool2) => bool2 ? 2 : 1,
    back: (u32) => u32 !== 1
  };
  return {
    caml_pasta_fp_plonk_index_create: {
      args: [
        // gates
        wasm2.WasmFpGateVector,
        // public_
        void 0,
        // lookup_tables
        void 0,
        // runtime_table_cfgs
        void 0,
        // prev_challenges
        void 0,
        // srs
        wasm2.WasmFpSrs,
        // lazy_mode
        void 0
      ],
      res: wasm2.WasmPastaFpPlonkIndex
    },
    caml_pasta_fq_plonk_index_create: {
      args: [
        // gates
        wasm2.WasmFqGateVector,
        // public_
        void 0,
        // lookup_tables
        void 0,
        // runtime_table_cfgs
        void 0,
        // prev_challenges
        void 0,
        // srs
        wasm2.WasmFqSrs,
        // lazy_mode
        void 0
      ],
      res: wasm2.WasmPastaFqPlonkIndex
    },
    caml_pasta_fp_plonk_verifier_index_create: {
      args: [wasm2.WasmPastaFpPlonkIndex],
      res: wasm2.WasmFpPlonkVerifierIndex
    },
    caml_pasta_fq_plonk_verifier_index_create: {
      args: [wasm2.WasmPastaFqPlonkIndex],
      res: wasm2.WasmFqPlonkVerifierIndex
    },
    caml_pasta_fp_plonk_proof_create: {
      args: [
        // index
        wasm2.WasmPastaFpPlonkIndex,
        // witness
        wasm2.WasmVecVecFp,
        // runtime tables
        void 0,
        // prev_challenges
        void 0,
        // prev_svgs
        void 0
      ],
      res: wasm2.WasmFpProverProof
    },
    caml_pasta_fq_plonk_proof_create: {
      args: [
        // index
        wasm2.WasmPastaFqPlonkIndex,
        // witness
        wasm2.WasmVecVecFq,
        // runtime tables
        void 0,
        // prev_challenges
        void 0,
        // prev_svgs
        void 0
      ],
      res: wasm2.WasmFqProverProof
    },
    caml_pasta_fp_plonk_proof_verify: {
      args: [wasm2.WasmFpPlonkVerifierIndex, wasm2.WasmFpProverProof],
      res: bool
    },
    caml_pasta_fq_plonk_proof_verify: {
      args: [wasm2.WasmFqPlonkVerifierIndex, wasm2.WasmFqProverProof],
      res: bool
    },
    caml_pasta_fp_plonk_proof_batch_verify: {
      args: [
        void 0,
        void 0
        /* UintXArray */
      ],
      res: bool
    },
    caml_pasta_fq_plonk_proof_batch_verify: {
      args: [
        void 0,
        void 0
        /* UintXArray */
      ],
      res: bool
    },
    caml_fp_srs_create_parallel: {
      args: [
        void 0
        /*number*/
      ],
      res: wasm2.WasmFpSrs
    },
    caml_fq_srs_create_parallel: {
      args: [
        void 0
        /*number*/
      ],
      res: wasm2.WasmFqSrs
    },
    caml_fp_srs_get_lagrange_basis: {
      disabled: true,
      args: [
        wasm2.WasmFpSrs,
        void 0
        /* number */
      ],
      // TODO: returning a UintXArray does not work:
      // the worker wrapper excepts the return value to be a number
      // that can be stored in a single u32.
      // A UintXArray is coerced into a 0 pointer, which doesn't trigger `wait_until_non_zero()`,
      // which means the main worker just keeps spinning waiting for a response.
      // A proper solution would be to wrap the return value in a pointer!
      res: void 0
    },
    caml_fq_srs_get_lagrange_basis: {
      disabled: true,
      args: [
        wasm2.WasmFqSrs,
        void 0
        /* number */
      ],
      // TODO: returning a UintXArray does not work, see above
      res: void 0
    },
    caml_fp_srs_b_poly_commitment: {
      args: [
        wasm2.WasmFpSrs,
        void 0
        /*Uint8Array*/
      ],
      res: wasm2.WasmFpPolyComm
    },
    caml_fq_srs_b_poly_commitment: {
      args: [
        wasm2.WasmFqSrs,
        void 0
        /*Uint8Array*/
      ],
      res: wasm2.WasmFqPolyComm
    },
    fp_oracles_create: {
      args: [void 0, wasm2.WasmFpPlonkVerifierIndex, wasm2.WasmFpProverProof],
      res: wasm2.WasmFpOracles
    },
    fq_oracles_create: {
      args: [void 0, wasm2.WasmFqPlonkVerifierIndex, wasm2.WasmFqProverProof],
      res: wasm2.WasmFqOracles
    },
    caml_fp_srs_batch_accumulator_check: {
      args: [
        wasm2.WasmFpSrs,
        void 0,
        void 0
        /* UintXArray */
      ],
      res: bool
    },
    caml_fq_srs_batch_accumulator_check: {
      args: [
        wasm2.WasmFqSrs,
        void 0,
        void 0
        /* UintXArray */
      ],
      res: bool
    },
    caml_fp_srs_lagrange_commitment: {
      args: [
        wasm2.WasmFpSrs,
        void 0,
        void 0
        /* number */
      ],
      res: wasm2.WasmFpPolyComm
    },
    caml_fq_srs_lagrange_commitment: {
      args: [
        wasm2.WasmFqSrs,
        void 0,
        void 0
        /* number */
      ],
      res: wasm2.WasmFqPolyComm
    },
    caml_fp_srs_lagrange_commitments_whole_domain: {
      args: [
        wasm2.WasmFpSrs,
        void 0
        /* number */
      ],
      res: void 0
    },
    caml_fq_srs_lagrange_commitments_whole_domain: {
      args: [
        wasm2.WasmFqSrs,
        void 0
        /* number */
      ],
      res: void 0
    }
  };
}

